							+ extra_edge_list_pos * sizeof(uint32_t))))
			   & 0x80000000u)
				       == 0) {
			extra_edge_list_pos++;
			e->parent_count++;
		}
	}
	git_oid_cpy(&e->sha1, &file->oid_lookup[pos]);
	return 0;
